const items = $input.all();

return items.map(item => {
  const base64 = String(item.json.file_content || "")
    .replace(/\s/g, "");

  return {
    json: {
      ...item.json,
      image_data_url: `data:image/jpeg;base64,${base64}`,
      base64_length: base64.length,
      base64_start: base64.substring(0, 30),
      base64_end: base64.substring(base64.length - 30)
    }
  };
});
